CREATE TABLE public.barbers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, position int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, price numeric(10,2) NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), barber_id uuid REFERENCES public.barbers(id) ON DELETE SET NULL, barber_name text NOT NULL, service_name text NOT NULL, price numeric(10,2) NOT NULL, payment_method text NOT NULL CHECK (payment_method IN ('dinheiro','pix','cartao')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.barbers, public.services, public.appointments TO anon, authenticated;
GRANT ALL ON public.barbers, public.services, public.appointments TO service_role;
ALTER TABLE public.barbers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.services ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.appointments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "open access" ON public.barbers FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY "open access" ON public.services FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY "open access" ON public.appointments FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
